from lib2to3.pgen2 import token
from lib2to3.pygram import python_symbols as syms
from lib2to3 import fixer_base
from lib2to3.fixer_util import Name, Call, find_binding
bind_warning = b'Calls to builtin next() possibly shadowed by global binding'

class FixNextCall(fixer_base.BaseFix):
    BM_compatible = True
    PATTERN = b"\n    power< base=any+ trailer< '.' attr='next' > trailer< '(' ')' > >\n    |\n    power< head=any+ trailer< '.' attr='next' > not trailer< '(' ')' > >\n    |\n    global=global_stmt< 'global' any* 'next' any* >\n    "
    order = b'pre'

    def start_tree(self, tree, filename):
        super(FixNextCall, self).start_tree(tree, filename)
        n = find_binding(b'next', tree)
        if n:
            self.warning(n, bind_warning)
            self.shadowed_next = True
        else:
            self.shadowed_next = False
        return

    def transform(self, node, results):
        base = results.get(b'base')
        attr = results.get(b'attr')
        name = results.get(b'name')
        if base:
            if self.shadowed_next:
                pass
            else:
                base = [n.clone() for n in base]
                base[0].prefix = b''
                node.replace(Call(Name(b'next', prefix=node.prefix), base))
        elif name:
            pass
        elif attr:
            if is_assign_target(node):
                head = results[b'head']
                if (b'').join([str(n) for n in head]).strip() == b'__builtin__':
                    self.warning(node, bind_warning)
                return
        elif b'global' in results:
            self.warning(node, bind_warning)
            self.shadowed_next = True
        return


def is_assign_target(node):
    assign = find_assign(node)
    if assign is None:
        return False
    else:
        for child in assign.children:
            if child.type == token.EQUAL:
                return False
            if is_subtree(child, node):
                return True

        return False


def find_assign(node):
    if node.type == syms.expr_stmt:
        return node
    else:
        if node.type == syms.simple_stmt or node.parent is None:
            return
        return find_assign(node.parent)


def is_subtree(root, node):
    if root == node:
        return True
    return any(is_subtree(c, node) for c in root.children)
